<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; class baidu extends lib { var $log_id = 'baidu'; public function __construct() { add_filter( 'qqworld-collector-settings-nav-tabs', array($this, 'add_nav_tab') ); add_action( 'qqworld-collector-settings-nav-sections', array($this, 'add_nav_section') ); add_action( 'init', array($this, 'initialize') ); add_action( 'qqworld-collector-baidu-remove-actions', array($this, 'remove_actions') ); add_action( 'qqworld-collector-submit-link-to-baidu', array($this, 'submit_post'), 10, 2 ); add_action( 'qqworld-collector-submit-urls-to-baidu', array($this, 'submit_urls'), 10, 2 ); add_action( 'qqworld-collector-push-to-xiongzhang-number', array($this, 'push_post'), 10, 2 ); add_action( 'qqworld-collector-push-url-to-xiongzhang-number', array($this, 'push_urls'), 10, 2 ); } public function init() {} public function add_nav_tab($nav_tabs) { $nav_tabs['baidu'] = __('Baidu', $this->text_domain); return $nav_tabs; } public function add_nav_section() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'settings-baidu.php'; } public function initialize() { if ($this->options->qc_baidu_link_submit_enabled == 1 && !empty($this->options->qc_baidu_link_submit_post_types)) { foreach ($this->options->qc_baidu_link_submit_post_types as $post_type) { add_action( "save_post_{$post_type}", array($this, 'submit_link_to_baidu'), 10, 3 ); } } if ($this->options->qc_xiongzhang_enabled == 1 && !empty($this->options->qc_xiongzhang_post_types)) { foreach ($this->options->qc_xiongzhang_post_types as $post_type) { add_action( "save_post_{$post_type}", array($this, 'push_to_xiongzhang_number'), 10, 3 ); } } } public function remove_actions() { if ($this->options->qc_baidu_link_submit_enabled == 1 && !empty($this->options->qc_baidu_link_submit_post_types)) { foreach ($this->options->qc_baidu_link_submit_post_types as $post_type) { if (has_action( "save_post_{$post_type}", array($this, 'submit_link_to_baidu') )) remove_action( "save_post_{$post_type}", array($this, 'submit_link_to_baidu') ); } } if ($this->options->qc_xiongzhang_enabled == 1 && !empty($this->options->qc_xiongzhang_post_types)) { foreach ($this->options->qc_xiongzhang_post_types as $post_type) { if (has_action( "save_post_{$post_type}", array($this, 'push_to_xiongzhang_number') )) remove_action( "save_post_{$post_type}", array($this, 'push_to_xiongzhang_number') ); } } } public function submit($urls, $type = 'normal') { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to Baidu $urls ('.$type.'):', print_r($urls, true) ); $host = parse_url($urls[0]); $api = 'http://data.zz.baidu.com/urls?site='.$host['host'].'&token='.$this->options->qc_baidu_link_submit_token; if ($type == 'mip') $api .= '&type=mip'; $ch = curl_init(); $options = array( CURLOPT_URL => $api, CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_POSTFIELDS => implode("\n", $urls), CURLOPT_HTTPHEADER => array('Content-Type: text/plain'), ); curl_setopt_array($ch, $options); $result = curl_exec($ch); $result = json_decode($result, true); if (isset($result['error'])) { do_action( 'qqworld-collector-log', $this->log_id, 'Submit Link to Baidu failed, ERROR:', print_r($result['message'], true) ); return false; } return true; } public function submit_link_to_baidu($post_ID, $post, $update) { if ($post->post_status != 'publish') return; if (!wp_next_scheduled('qqworld-collector-submit-link-to-baidu', array($post_ID, $post))) { wp_schedule_single_event( time() + 5, 'qqworld-collector-submit-link-to-baidu', array($post_ID, $post) ); } $urls = array(get_permalink($post_ID)); $this->submit($urls); if ($this->options->qc_baidu_link_submit_mip) $this->submit($urls, 'mip'); } public function submit_urls($urls, $post_type) { if ($this->options->qc_baidu_link_submit_enabled == 1 && !empty($this->options->qc_baidu_link_submit_post_types) && in_array($post_type, $this->options->qc_baidu_link_submit_post_types)) { $this->submit($urls); if ($this->options->qc_baidu_link_submit_mip) $this->submit($urls, 'mip'); } } public function submit_post($post_ID, $post) { $urls = array(get_permalink($post_ID)); $this->submit($urls); if ($this->options->qc_baidu_link_submit_mip) $this->submit($urls, 'mip'); } public function push_to_xiongzhang_number($post_ID, $post, $update) { if ($post->post_status != 'publish') return; if (!wp_next_scheduled('qqworld-collector-push-to-xiongzhang-number', array($post_ID, $post))) { wp_schedule_single_event( time() + 5, 'qqworld-collector-push-to-xiongzhang-number', array($post_ID, $post) ); } $this->push_post($post_ID, $post); } public function push_urls($url, $post_type) { do_action( 'qqworld-collector-log', $this->log_id, 'Post to XiongZhang Number $url:', print_r($url, true) ); if ($this->options->qc_xiongzhang_enabled == 1 && !empty($this->options->qc_xiongzhang_post_types) && in_array($post_type, $this->options->qc_xiongzhang_post_types)) { $type = 'realtime'; $query = array( 'appid' => $this->options->qc_xiongzhang_appid, 'token' => $this->options->qc_xiongzhang_token, 'type' => $type ); $api_url = 'http://data.zz.baidu.com/urls?' . http_build_query($query); $response = wp_remote_post($api_url, array( 'headers' => array('Accept-Encoding'=>'','Content-Type'=>'text/plain'), 'timeout' => 10, 'sslverify' => false, 'blocking' => true, 'body' => $url )); $res = json_decode($response['body'], true); if ( is_wp_error( $response ) ) { do_action( 'qqworld-collector-log', $this->log_id, '01 POST ERROR:', print_r($res, true) ); } else { $success = true; do_action( 'qqworld-collector-log', $this->log_id, '01 POST SUCCESS:', print_r($res, true) ); $type_arr = explode(",", $type); foreach ($type_arr as $type) { if (isset($res['success_'.$type]) && $res['success_'.$type]==1) { do_action( 'qqworld-collector-log', $this->log_id, 'SUCCESS: ', $url.'|'.$type.'|'.$res['success_'.$type] ); } elseif (isset($res['remain_'.$type]) && $res['remain_'.$type]==0){ do_action( 'qqworld-collector-log', $this->log_id, 'FAIL: ', $url.'|'.$type.'|'.__('Reached the limit', $this->text_domain) ); $success = false; } else { do_action( 'qqworld-collector-log', $this->log_id, 'FAIL: ', $url.'|'.$type.'|'.__('Submited failed', $this->text_domain) ); $success = false; } } if (!$success) { $type = 'batch'; $query = array( 'appid' => $this->options->qc_xiongzhang_appid, 'token' => $this->options->qc_xiongzhang_token, 'type' => $type ); $api_url = 'http://data.zz.baidu.com/urls?' . http_build_query($query); $response = wp_remote_post($api_url, array( 'headers' => array('Accept-Encoding'=>'','Content-Type'=>'text/plain'), 'timeout' => 10, 'sslverify' => false, 'blocking' => true, 'body' => $url )); if ( is_wp_error( $response ) ) { do_action( 'qqworld-collector-log', $this->log_id, '01 POST ERROR:', print_r($res, true) ); } else { do_action( 'qqworld-collector-log', $this->log_id, '01 POST SUCCESS:', print_r($res, true) ); $type_arr = explode(",", $type); foreach ($type_arr as $type) { if (isset($res['success_'.$type]) && $res['success_'.$type]==1) { do_action( 'qqworld-collector-log', $this->log_id, 'SUCCESS: ', $url.'|'.$type.'|'.$res['success_'.$type] ); } elseif (isset($res['remain_'.$type]) && $res['remain_'.$type]==0){ do_action( 'qqworld-collector-log', $this->log_id, 'FAIL: ', $url.'|'.$type.'|'.__('Reached the limit', $this->text_domain) ); $success = false; } else { do_action( 'qqworld-collector-log', $this->log_id, 'FAIL: ', $url.'|'.$type.'|'.__('Submited failed', $this->text_domain) ); $success = false; } } } } } } return $success; } public function push_post($post_ID, $post) { $ORIGINAL = 3600; $status = get_post_meta( $post_ID, 'xiongzhang_submit', true); $type=''; if ($status == 2) { return; } elseif ($status == 1) { if( ($this->options->qc_xiongzhang_original=='1') && (time()-get_post_time('G', true, $post)<$ORIGINAL) ) $type = 'original'; else return; } else { if( date('Y-m-d') == date('Y-m-d',get_post_time('G', true, $post)) ) { if( ($this->options->qc_xiongzhang_original=='1') && (time()-get_post_time('G', true, $post)<$ORIGINAL) ) $type = 'original'; else $type = 'realtime'; } else { $type='batch'; } $type='realtime'; } $query = array( 'appid' => $this->options->qc_xiongzhang_appid, 'token' => $this->options->qc_xiongzhang_token, 'type' => $type ); $api_url = 'http://data.zz.baidu.com/urls?' . http_build_query($query); $response = wp_remote_post($api_url, array( 'headers' => array('Accept-Encoding'=>'','Content-Type'=>'text/plain'), 'timeout' => 10, 'sslverify' => false, 'blocking' => true, 'body' => get_permalink($post_ID) )); do_action( 'qqworld-collector-log', $this->log_id, '$type', print_r($type, true) ); $res = json_decode($response['body'], true); if ( is_wp_error( $response ) ) { do_action( 'qqworld-collector-log', $this->log_id, '01 POST ERROR:', print_r($res, true) ); } else { do_action( 'qqworld-collector-log', $this->log_id, '01 POST SUCCESS:', print_r($res, true) ); $type_arr = explode(",", $type); foreach ($type_arr as $type) { if (isset($res['success_'.$type]) && $res['success_'.$type]==1) { if ($type == 'batch') { update_post_meta($post_ID, 'xiongzhang_submit', '-1'); } else { update_post_meta($post_ID, 'xiongzhang_submit', '1'); if ($res['success_'.$type]==1) { update_post_meta($post_ID, 'xiongzhang_submit', '2'); } } do_action( 'qqworld-collector-log', $this->log_id, 'SUCCESS: ', get_permalink($post_ID).'|'.$type.'|'.$res['success_'.$type] ); } elseif (isset($res['remain_'.$type]) && $res['remain_'.$type]==0){ do_action( 'qqworld-collector-log', $this->log_id, 'FAIL: ', get_permalink($post_ID).'|'.$type.'|'.__('Reached the limit', $this->text_domain) ); } else { do_action( 'qqworld-collector-log', $this->log_id, 'FAIL: ', get_permalink($post_ID).'|'.$type.'|'.__('Submited failed', $this->text_domain) ); } } } } } ?>